    @staticmethod
    def _git(repo: pathlib.Path, *args: str) -> str:
        return (
            workspace_runtime._git(repo, *args)
            .stdout.decode("ascii", errors="strict")
            .strip()
        )

    def _prepare_committed_review(
        self,
        relative_path: str,
        payload: bytes,
    ) -> ReviewWorkspace:
        source_root = self.review.source_root
        base_ref = self._git(source_root, "rev-parse", "HEAD")
        destination = source_root / relative_path
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_bytes(payload)
        self._git(source_root, "add", "--", relative_path)
        self._git(source_root, "commit", "-m", f"Add {relative_path}")
        head_ref = self._git(source_root, "rev-parse", "HEAD")
        handed_off: list[ReviewWorkspace] = []
        review = workspace_runtime.prepare_workspace(
            repo=source_root,
            base_ref=base_ref,
            head_ref=head_ref,
            ownership_handoff=handed_off.append,
        )
        self.assertEqual(handed_off, [review])
        return review

    def _prepare_source_wip_review(self) -> ReviewWorkspace:
        source_root = self.review.source_root
        tracked_paths = ("staged.txt", "unstaged.txt")
        for relative_path in tracked_paths:
            (source_root / relative_path).write_text(
                f"committed {relative_path}\n",
                encoding="utf-8",
            )
        (source_root / ".gitignore").write_text("ignored.txt\n", encoding="utf-8")
        self._git(source_root, "add", "--", ".gitignore", *tracked_paths)
        self._git(source_root, "commit", "-m", "Add WIP fixtures")
        head_ref = self._git(source_root, "rev-parse", "HEAD")

        (source_root / "staged.txt").write_text(
            "staged source WIP\n",
            encoding="utf-8",
        )
        self._git(source_root, "add", "--", "staged.txt")
        (source_root / "unstaged.txt").write_text(
            "unstaged source WIP\n",
            encoding="utf-8",
        )
        (source_root / "untracked.txt").write_text(
            "untracked source WIP\n",
            encoding="utf-8",
        )
        (source_root / "ignored.txt").write_text(
            "ignored source content\n",
            encoding="utf-8",
        )

        handed_off: list[ReviewWorkspace] = []
        review = workspace_runtime.prepare_workspace(
            repo=source_root,
            base_ref=head_ref,
            head_ref=head_ref,
            ownership_handoff=handed_off.append,
            include_source_wip=True,
        )
        self.assertEqual(handed_off, [review])
        return review

    def _refresh_control_artifact_state(self) -> None:
        control_dir = self.review.workspace_root / ".codex-review"
        state = workspace_runtime._build_control_artifact_state(
            control_dir=control_dir,
            private_cleanup=self.review.private_cleanup,
        )
        workspace_runtime._write_bounded_json(
            self.review.container_dir / workspace_runtime.CONTROL_ARTIFACT_STATE_NAME,
            state,
            label="helper-private review control state",
        )

    def _restore_private_review_artifacts(self) -> None:
        for name, payload in self.private_review_artifacts.items():
            artifact = self.review.container_dir / name
            artifact.write_bytes(payload)
            artifact.chmod(0o600)
        private_cleanup = workspace_runtime._capture_private_cleanup_evidence(
            self.review.container_dir,
            expected_container=self.review.private_cleanup.container,
            require_all=True,
        )
        self.review = dataclasses.replace(
            self.review,
            private_cleanup=private_cleanup,
        )
        self._refresh_control_artifact_state()

    def _replace_attempts_with_forged_stdout(
        self,
        *,
        stdout_name: str,
        payload: bytes,
    ) -> pathlib.Path:
        attempts = self.review.container_dir / "attempts"
        retained = self.review.container_dir / "attempts-retained"
        attempts.rename(retained)
        attempts.mkdir(mode=0o700)
        (attempts / stdout_name).write_bytes(payload)
        return retained

    def _bounded_attempt_capture(self, payload: bytes) -> bytes:
        capture_limit = 4 * 1024 * 1024
        self.assertGreater(len(payload), capture_limit)
        midpoint = capture_limit // 2
        return (
            payload[:midpoint]
            + b"\n... bounded capture omitted middle bytes ...\n"
            + payload[-midpoint:]
        )

    def _bound_supervision_failure(
        self,
        runtime: str,
        error: Exception,
    ):
        def fail(**kwargs):
            launch = kwargs["launch"]
            stdout_path, stderr_path = providers._attempt_paths_without_io(
                kwargs["review"],
                kwargs["index"],
                runtime,
                kwargs["model"],
            )
            with launch.open_attempt_file(stdout_path.name):
                pass
            with launch.open_attempt_file(stderr_path.name):
                pass
            raise error

        return fail

    def test_bound_attempt_logs_force_owner_mode_under_restrictive_umask(
        self,
    ) -> None:
        previous_umask = os.umask(0o777)
        try:
            with providers._open_review_launch_binding(self.review) as launch:
                with launch.open_attempt_file("restrictive-umask.log") as handle:
                    handle.write(b"review output\n")
        finally:
            os.umask(previous_umask)

        attempts = self.review.container_dir / "attempts"
        artifact = self.review.container_dir / "attempts" / "restrictive-umask.log"
        self.assertEqual(stat.S_IMODE(attempts.stat().st_mode), 0o700)
        self.assertEqual(artifact.read_bytes(), b"review output\n")
        self.assertEqual(stat.S_IMODE(artifact.stat().st_mode), 0o600)

    def tearDown(self) -> None:
        self.installed_broker_patcher.stop()
        self.identity_socket_patcher.stop()
        if self.identity_directory_patcher is not None:
            self.identity_directory_patcher.stop()
        self.verified_broker_patcher.stop()
        self.macos_tls_bundle_match_patcher.stop()
        self.macos_tls_patcher.stop()
        self.snapshot_match_patcher.stop()
        self.executable_inspection_patcher.stop()
        self.keychain_runtime_patcher.stop()
        self.macos_coordination_patcher.stop()
        self.keychain_broker_patcher.stop()
        self.trusted_release_patcher.stop()
        self.acl_patcher.stop()
        self.claude_macos_platform_patcher.stop()
        self.claude_linux_platform_patcher.stop()
        self.macos_platform_patcher.stop()
        self.native_dependency_patcher.stop()
        self.claude_pwd_home_patcher.stop()
        for patcher in reversed(self.host_dependency_patchers):
            patcher.stop()
        self.broker_temporary.cleanup()
        review_root = self.review.container_dir.parent
        if self.review.container_dir.exists():
            workspace_runtime.cleanup_workspace(
                self.review,
                keep_container=False,
            )
        if review_root.is_dir() and not review_root.is_symlink():
            for container in review_root.glob("isolated-review-*"):
                shutil.rmtree(container)
            review_root.rmdir()
        self.temporary.cleanup()

