    def assert_cleanup_diagnostic_preserves_original_cause(
        self,
        error: BaseException,
        original_cause: BaseException,
    ) -> None:
        direct_cause = error.__cause__
        if direct_cause is original_cause:
            return
        self.assertIsInstance(
            direct_cause,
            providers.ClaudeCredentialCleanupDiagnostic,
        )
        current = direct_cause
        seen: set[int] = set()
        for _ in range(32):
            if current is original_cause:
                return
            identity = id(current)
            if identity in seen:
                break
            seen.add(identity)
            if isinstance(current.__cause__, BaseException):
                current = current.__cause__
                continue
            break
        self.fail("original cause is missing from the visible cleanup cause chain")

    def format_exception_text(self, error: BaseException) -> str:
        return "".join(
            traceback.format_exception(
                type(error),
                error,
                error.__traceback__,
            )
        )

    def assert_exception_visible_exact_or_rendered(
        self,
        error: BaseException,
        expected: BaseException,
    ) -> None:
        if providers._claude_visible_error_chain_contains(error, expected):
            return
        self.assertIn(
            f"{type(expected).__name__}: {expected}",
            self.format_exception_text(error),
        )

    def assert_cleanup_diagnostic_visible(
        self,
        error: BaseException,
    ) -> None:
        pending = [error]
        visited: set[int] = set()
        for _ in range(16):
            if not pending:
                break
            current = pending.pop(0)
            identity = id(current)
            if identity in visited:
                continue
            visited.add(identity)
            if any(
                "Claude credential operation also had a cleanup failure" in note
                for note in getattr(current, "__notes__", ())
            ):
                return
            if isinstance(
                current,
                providers.ClaudeCredentialCleanupDiagnostic,
            ):
                return
            for related in (current.__cause__, current.__context__):
                if related is not None:
                    pending.append(related)
        self.fail("Claude credential cleanup diagnostic is missing")

    def assert_persistence_diagnostic_visible(
        self,
        error: BaseException,
    ) -> None:
        pending = [error]
        visited: set[int] = set()
        for _ in range(16):
            if not pending:
                break
            current = pending.pop(0)
            identity = id(current)
            if identity in visited:
                continue
            visited.add(identity)
            if any(
                providers.CLAUDE_REFRESH_PERSISTENCE_DIAGNOSTIC in note
                for note in getattr(current, "__notes__", ())
            ):
                return
            if isinstance(
                current,
                providers.ClaudeCredentialPersistenceDiagnostic,
            ) and providers.CLAUDE_REFRESH_PERSISTENCE_DIAGNOSTIC in str(current):
                return
            for related in (current.__cause__, current.__context__):
                if related is not None:
                    pending.append(related)
        self.fail("Claude persistence diagnostic is missing from the exception chain")

