    def test_claude_macos_attempt_reuses_proxy_tls_snapshot_after_source_mutation(
        self,
    ) -> None:
        executable = self.review.container_dir / "verified-claude"
        executable.write_bytes(b"snapshot")
        source = self.review.container_dir / "caller-ca.pem"
        source_material = (CERTIFICATE_FIXTURES / "trust-root-valid.pem").read_bytes()
        source.write_bytes(source_material)
        source.chmod(0o600)
        trust_state = providers.ClaudeTrustSessionState()
        real_proxy_tls = providers._claude_proxy_tls_environment

        def snapshot_then_mutate(*args: object, **kwargs: object):
            prepared = real_proxy_tls(*args, **kwargs)
            source.write_bytes(b"mutated after proxy snapshot")
            return prepared

        def inspect_final_tls_input(
            _review: ReviewWorkspace,
            env: dict[str, str],
            **kwargs: object,
        ) -> dict[str, str]:
            snapshot = pathlib.Path(env["SSL_CERT_FILE"])
            self.assertNotEqual(snapshot, source)
            self.assertEqual(snapshot.read_bytes(), source_material)
            self.assertEqual(
                kwargs["expected_snapshot_sha256"],
                trust_state.proxy_tls_snapshot_sha256,
            )
            raise ReviewError("stop after TLS snapshot assertion")

        with (
            mock.patch.object(providers, "_is_claude_linux_host", return_value=False),
            mock.patch.object(
                providers,
                "_with_claude_review_tool_path",
                side_effect=lambda _review, env: dict(env),
            ),
            mock.patch.object(
                providers,
                "_claude_proxy_tls_environment",
                side_effect=snapshot_then_mutate,
            ),
            mock.patch.object(
                providers,
                "_prepare_claude_tls_environment",
                side_effect=inspect_final_tls_input,
            ),
            self.assertRaisesRegex(
                ReviewError,
                "stop after TLS snapshot assertion",
            ),
        ):
            providers._claude_attempt(
                review=self.review,
                model=providers.CLAUDE_MODELS[0],
                index=1,
                env={
                    "ANTHROPIC_API_KEY": FIXTURES["api-key-a"],
                    "SSL_CERT_FILE": str(source),
                },
                executable=executable,
                executable_evidence=self.claude_executable_evidence,
                trust_state=trust_state,
            )

        self.assertEqual(source.read_bytes(), b"mutated after proxy snapshot")
        self.assertIsNotNone(trust_state.proxy_tls_snapshot_sha256)

    def test_claude_post_run_refresh_failure_reports_completed_attempt(self) -> None:
        executable = self.review.container_dir / "verified-claude"
        executable.write_bytes(b"snapshot")
        providers.write_json(
            self.review.container_dir / "claude-runtime.json",
            {
                "phase": "publisher-and-capabilities-verified",
                "outer_sandbox": {"status": "pending-runtime-launch"},
                "authentication": {"status": "pending"},
            },
        )
        completed = Completed(
            argv=("claude",),
            returncode=0,
            stdout=b"{}",
            stderr=b"",
        )
        process_binding = providers._ClaudeRuntimeProcessBinding(
            process_id=4321,
            session_id=4321,
            process_group=4321,
        )
        prepare_runtime_process = mock.Mock(return_value=process_binding)
        bind_runtime_process = mock.Mock()

        @contextlib.contextmanager
        def runtime(
            _review,
            env,
            _refresh_lock_protocol,
            *,
            process_started,
            process_quiescent,
        ):
            self.assertFalse(process_started())
            self.assertFalse(process_quiescent())
            yield providers._ClaudeKeychainRuntimeEnvironment(
                dict(env),
                prepare_runtime_process,
                bind_runtime_process,
            )
            self.assertTrue(process_started())
            self.assertTrue(process_quiescent())
            raise providers.ClaudeKeychainCredentialUnavailable(
                "refresh persistence failed"
            )

        def run_review(*_args: object, **kwargs: object) -> Completed:
            prepare_process_spawned = kwargs.get("prepare_process_spawned")
            on_process_spawned = kwargs.get("on_process_spawned")
            on_process_starting = kwargs.get("on_process_starting")
            on_process_started = kwargs.get("on_process_started")
            on_process_quiescent = kwargs.get("on_process_quiescent")
            assert callable(prepare_process_spawned)
            assert callable(on_process_spawned)
            assert callable(on_process_starting)
            assert callable(on_process_started)
            assert callable(on_process_quiescent)
            binding = prepare_process_spawned(4321)
            on_process_spawned(binding)
            on_process_starting()
            on_process_started()
            on_process_quiescent()
            return completed

        with (
            mock.patch.object(providers, "_is_claude_linux_host", return_value=False),
            mock.patch.object(
                providers,
                "_with_claude_review_tool_path",
                side_effect=lambda _review, env: dict(env),
            ),
            mock.patch.object(
                providers,
                "_prepare_claude_tls_environment",
                side_effect=lambda _review, env, **_kwargs: dict(env),
            ),
            mock.patch.object(
                providers, "_claude_keychain_runtime", side_effect=runtime
            ),
            mock.patch.object(
                providers,
                "_claude_connect_proxy",
                return_value=contextlib.nullcontext(43210),
            ),
            mock.patch.object(
                providers,
                "_claude_review_sandbox_profile",
                return_value="(version 1)",
            ),
            mock.patch.object(providers, "run", side_effect=run_review),
            mock.patch.object(
                providers,
                "_validate_claude_attempt_stream",
                return_value={
                    "classification": "accepted",
                    "findings": "No findings.",
                },
            ) as validate_stream,
            self.assertRaisesRegex(
                providers.ClaudeCredentialInspectionInconclusive,
                "post-attempt credential persistence was inconclusive",
            ) as raised,
        ):
            providers._claude_attempt(
                review=self.review,
                model=providers.CLAUDE_MODELS[0],
                index=1,
                env={},
                executable=executable,
                executable_evidence=self.claude_executable_evidence,
                refresh_lock_protocol=self.claude_refresh_lock_protocol,
            )

        validate_stream.assert_called_once()
        report = common.read_json(self.review.container_dir / "claude-runtime.json")
        self.assertEqual(
            report["phase"],
            "authentication-inspection-inconclusive",
        )
        self.assertEqual(report["status"], "inconclusive")
        self.assertEqual(report["outer_sandbox"]["status"], "enforced-at-launch")
        self.assertEqual(
            report["authentication"]["failure_class"],
            "refresh-persistence",
        )
        self.assertEqual(report["attempt"]["category"], "inconclusive")
        self.assertEqual(report["attempt"]["returncode"], 0)
        attempt = getattr(
            raised.exception,
            "_codex_claude_persistence_attempt",
        )
        self.assertIsInstance(attempt, providers.Attempt)
        self.assertEqual(attempt.category, "inconclusive")
        self.assertEqual(attempt.returncode, 0)
        prepare_runtime_process.assert_called_once_with(4321)
        bind_runtime_process.assert_called_once_with(process_binding)

    def test_claude_quiescence_mask_call_results_restore_owner(self) -> None:
        attempt = providers._claude_attempt_with_output
        instructions = tuple(dis.get_instructions(attempt))
        injection_sites: list[tuple[int, int]] = []
        for index, instruction in enumerate(instructions[:-1]):
            if not instruction.opname.startswith("CALL"):
                continue
            loaded_globals = [
                candidate.argval
                for candidate in instructions[max(0, index - 12) : index]
                if candidate.opname == "LOAD_GLOBAL"
            ]
            if not loaded_globals or loaded_globals[-1] != "block_forwarded_signals":
                continue
            result_instruction = instructions[index + 1]
            if not (
                result_instruction.opname == "STORE_FAST"
                and result_instruction.argval == "quiescence_mask"
            ):
                continue
            source_line = next(
                line
                for candidate in reversed(instructions[max(0, index - 12) : index + 1])
                if (
                    line := (
                        getattr(
                            getattr(candidate, "positions", None),
                            "lineno",
                            None,
                        )
                        or (
                            candidate.starts_line
                            if isinstance(candidate.starts_line, int)
                            and not isinstance(candidate.starts_line, bool)
                            else None
                        )
                    )
                )
                is not None
            )
            injection_sites.append((result_instruction.offset, source_line))

        self.assertEqual(len(injection_sites), 2, injection_sites)
        linux_source_line = min(line for _offset, line in injection_sites)
        completed = Completed(
            argv=("claude",),
            returncode=0,
            stdout=b"{}",
            stderr=b"",
        )
        executable = pathlib.Path("/verified/claude")
        prior_mask = {signal.SIGINT}

        for target_offset, source_line in injection_sites:
            linux = source_line == linux_source_line
            with self.subTest(
                platform="linux" if linux else "macos",
                target_offset=target_offset,
            ):
                mask_blocked = False
                interruption = RuntimeError(
                    "fixture quiescence mask CALL-result interruption"
                )
                output = mock.create_autospec(providers.AttemptOutput, instance=True)
                output.run_arguments.return_value = {}

                def block_signals(
                    *,
                    signal_mask_owner: object | None = None,
                ) -> set[signal.Signals]:
                    nonlocal mask_blocked
                    mask_blocked = True
                    if signal_mask_owner is not None:
                        signal_mask_owner.publish_previous_signal_mask(prior_mask)
                    return prior_mask

                def restore_mask(
                    previous: set[signal.Signals] | None,
                ) -> None:
                    nonlocal mask_blocked
                    self.assertIs(previous, prior_mask)
                    mask_blocked = False

                @contextlib.contextmanager
                def linux_runtime(*_args: object, **_kwargs: object):
                    yield mock.Mock(argv=("sandbox",), env={})

                @contextlib.contextmanager
                def keychain_runtime(
                    _review: ReviewWorkspace,
                    env: dict[str, str],
                    *_args: object,
                    **_kwargs: object,
                ):
                    yield dict(env)

                injected = False

                def interrupt_result_store(
                    frame: object,
                    event: str,
                    _argument: object,
                ) -> object:
                    nonlocal injected
                    if getattr(frame, "f_code", None) is not attempt.__code__:
                        return interrupt_result_store
                    setattr(frame, "f_trace_opcodes", True)
                    if (
                        not injected
                        and event == "opcode"
                        and getattr(frame, "f_lasti", None) == target_offset
                    ):
                        injected = True
                        raise interruption
                    return interrupt_result_store

                with contextlib.ExitStack() as stack:
                    stack.enter_context(
                        mock.patch.object(
                            providers,
                            "_is_claude_linux_host",
                            return_value=linux,
                        )
                    )
                    for name, side_effect in (
                        (
                            "_with_claude_review_tool_path",
                            lambda _review, env: dict(env),
                        ),
                        (
                            "_prepare_claude_tls_environment",
                            lambda _review, env, **_kwargs: dict(env),
                        ),
                    ):
                        stack.enter_context(
                            mock.patch.object(
                                providers,
                                name,
                                side_effect=side_effect,
                            )
                        )
                    stack.enter_context(
                        mock.patch.object(
                            providers,
                            "_update_claude_runtime_report",
                        )
                    )
                    stack.enter_context(
                        mock.patch.object(
                            providers,
                            "_record_claude_secondary_persistence_failure",
                        )
                    )
                    stack.enter_context(
                        mock.patch.object(
                            providers,
                            "run",
                            return_value=completed,
                        )
                    )
                    stack.enter_context(
                        mock.patch.object(
                            providers,
                            "block_forwarded_signals",
                            side_effect=block_signals,
                        )
                    )
                    restore = stack.enter_context(
                        mock.patch.object(
                            providers,
                            "restore_signal_mask",
                            side_effect=restore_mask,
                        )
                    )
                    if linux:
                        stack.enter_context(
                            mock.patch.object(
                                providers,
                                "_claude_linux_review_runtime",
                                side_effect=linux_runtime,
                            )
                        )
                    else:
                        stack.enter_context(
                            mock.patch.object(
                                providers,
                                "_claude_keychain_runtime",
                                side_effect=keychain_runtime,
                            )
                        )
                        stack.enter_context(
                            mock.patch.object(
                                providers,
                                "_claude_connect_proxy",
                                return_value=contextlib.nullcontext(43210),
                            )
                        )
                        stack.enter_context(
                            mock.patch.object(
                                providers,
                                "_claude_review_sandbox_profile",
                                return_value="(version 1)",
                            )
                        )
                    raised = stack.enter_context(self.assertRaises(RuntimeError))
                    try:
                        sys.settrace(interrupt_result_store)
                        attempt(
                            review=self.review,
                            model=providers.CLAUDE_MODELS[0],
                            index=1,
                            env={"ANTHROPIC_API_KEY": "fixture"},
                            executable=executable,
                            executable_evidence=self.claude_executable_evidence,
                            trust_state=providers.ClaudeTrustSessionState(),
                            launch=None,
                            refresh_lock_protocol=(self.claude_refresh_lock_protocol),
                            output=output,
                        )
                    finally:
                        sys.settrace(None)

                self.assertTrue(injected)
                self.assertIs(raised.exception, interruption)
                self.assertFalse(mask_blocked)
                restore.assert_called_once_with(prior_mask)

    def test_claude_quiescence_keeps_body_signal_across_restore_retry(
        self,
    ) -> None:
        completed = Completed(
            argv=("claude",),
            returncode=0,
            stdout=b"{}",
            stderr=b"",
        )
        executable = pathlib.Path("/verified/claude")
        prior_mask = {signal.SIGINT}

        class FixtureEvent:
            def __init__(self, set_error: BaseException | None = None) -> None:
                self._set = False
                self._set_error = set_error

            def is_set(self) -> bool:
                return self._set

            def set(self) -> None:
                if self._set_error is not None:
                    raise self._set_error
                self._set = True

        restore_error_factories: tuple[tuple[str, Callable[[], BaseException]], ...] = (
            (
                "forwarded-signal",
                lambda: providers.ForwardedSignal(signal.SIGINT),
            ),
            ("ordinary", lambda: OSError("fixture transient restore failure")),
        )

        for linux in (True, False):
            for restore_label, restore_error_factory in restore_error_factories:
                with self.subTest(
                    platform="linux" if linux else "macos",
                    restore_error=restore_label,
                ):
                    primary_signal = providers.ForwardedSignal(signal.SIGTERM)
                    restore_error = restore_error_factory()
                    quiescent_event = FixtureEvent(primary_signal)
                    observed_owners: list[providers._ClaudeSignalMaskOwner] = []

                    def block_signals(
                        *,
                        signal_mask_owner: (
                            providers._ClaudeSignalMaskOwner | None
                        ) = None,
                    ) -> set[signal.Signals]:
                        assert signal_mask_owner is not None
                        signal_mask_owner.publish_previous_signal_mask(prior_mask)
                        observed_owners.append(signal_mask_owner)
                        return prior_mask

                    @contextlib.contextmanager
                    def linux_runtime(*_args: object, **_kwargs: object):
                        yield mock.Mock(argv=("sandbox",), env={})

                    @contextlib.contextmanager
                    def keychain_runtime(
                        _review: ReviewWorkspace,
                        env: dict[str, str],
                        *_args: object,
                        **_kwargs: object,
                    ):
                        yield dict(env)

                    with contextlib.ExitStack() as stack:
                        stack.enter_context(
                            mock.patch.object(
                                providers,
                                "_is_claude_linux_host",
                                return_value=linux,
                            )
                        )
                        for name, side_effect in (
                            (
                                "_with_claude_review_tool_path",
                                lambda _review, env: dict(env),
                            ),
                            (
                                "_prepare_claude_tls_environment",
                                lambda _review, env, **_kwargs: dict(env),
                            ),
                        ):
                            stack.enter_context(
                                mock.patch.object(
                                    providers,
                                    name,
                                    side_effect=side_effect,
                                )
                            )
                        stack.enter_context(
                            mock.patch.object(
                                providers,
                                "_update_claude_runtime_report",
                            )
                        )
                        stack.enter_context(
                            mock.patch.object(
                                providers,
                                ("_record_claude_secondary_persistence_failure"),
                            )
                        )
                        stack.enter_context(
                            mock.patch.object(
                                providers,
                                "run",
                                return_value=completed,
                            )
                        )
                        stack.enter_context(
                            mock.patch.object(
                                providers.threading,
                                "Event",
                                return_value=quiescent_event,
                            )
                        )
                        stack.enter_context(
                            mock.patch.object(
                                providers,
                                "block_forwarded_signals",
                                side_effect=block_signals,
                            )
                        )
                        restore = stack.enter_context(
                            mock.patch.object(
                                providers,
                                "restore_signal_mask",
                                side_effect=(restore_error, None),
                            )
                        )
                        if linux:
                            stack.enter_context(
                                mock.patch.object(
                                    providers,
                                    "_claude_linux_review_runtime",
                                    side_effect=linux_runtime,
                                )
                            )
                        else:
                            stack.enter_context(
                                mock.patch.object(
                                    providers,
                                    "_claude_keychain_runtime",
                                    side_effect=keychain_runtime,
                                )
                            )
                            stack.enter_context(
                                mock.patch.object(
                                    providers,
                                    "_claude_connect_proxy",
                                    return_value=contextlib.nullcontext(43210),
                                )
                            )
                            stack.enter_context(
                                mock.patch.object(
                                    providers,
                                    "_claude_review_sandbox_profile",
                                    return_value="(version 1)",
                                )
                            )
                        raised = stack.enter_context(
                            self.assertRaises(providers.ForwardedSignal)
                        )
                        providers._claude_attempt(
                            review=self.review,
                            model=providers.CLAUDE_MODELS[0],
                            index=1,
                            env={"ANTHROPIC_API_KEY": "fixture"},
                            executable=executable,
                            executable_evidence=self.claude_executable_evidence,
                            refresh_lock_protocol=(self.claude_refresh_lock_protocol),
                        )

                    self.assertIs(raised.exception, primary_signal)
                    self.assertEqual(
                        restore.call_args_list,
                        [mock.call(prior_mask), mock.call(prior_mask)],
                    )
                    self.assertEqual(len(observed_owners), 1)
                    self.assertFalse(observed_owners[0].signal_mask_owner_active)
                    self.assert_cleanup_diagnostic_visible(primary_signal)

